def enabled(): return os.getenv("RECORD_FB_SCAN_20260830_EVENING","0").strip().lower() in {"1","true","yes","on"}
def _sheet(book,title,header):
    try:return book.worksheet(title)
    except Exception:
        ws=book.add_worksheet(title=title,rows=1000,cols=max(12,len(header)));ws.append_row(header,value_input_option="RAW");return ws

def run():
    if not enabled():return {"enabled":False}
    now=datetime.now(timezone.utc).isoformat(timespec="seconds")
    book=cozy_catalog._client().open_by_key(cozy_catalog.SHEET_ID)
    src=_sheet(book,"SourceRegistry",["created_at","source_id","source_url","owner_url","original_price_thb","original_description","availability","channels_json","lots_json","message_ids_json","status","notes"])
    own=_sheet(book,"OwnersAvailability",["checked_at","source_id","owner","source_url","owner_url","availability","owner_price_thb","deposit","utilities","reservation","status","notes"])
    sr=src.get_all_values();ora=own.get_all_values()
    si={r[1]:i for i,r in enumerate(sr[1:],2) if len(r)>1};oi={r[1]:i for i,r in enumerate(ora[1:],2) if len(r)>1}
    added=[];updated=[]
    for x in ITEMS:
        sid="facebook_marketplace_"+x["id"];url="https://www.facebook.com/marketplace/item/"+x["id"]+"/";owner_url="https://www.facebook.com/marketplace/profile/"+x["owner_id"]+"/?product_id="+x["id"]
        notes=json.dumps({"district":x["district"],"type":x["type"],"bedrooms":x["beds"],"bathrooms":x["baths"],"pool":x["pool"],"minimum_stay":x["stay"],"restrictions":x["restrictions"],"contact_internal":x["contact"],"photo_fingerprints":x["photos"],"last_checked":now,"contact_status":"not_sent_noninteractive_browser_action_requires_confirmation"},ensure_ascii=False)
        row=[now,sid,url,owner_url,x["price"],x["text"],x["availability"],"[]","{}","{}","new_needs_owner_reply",notes]
        if sid in si:src.update(f"A{si[sid]}:L{si[sid]}",[row],value_input_option="RAW");updated.append(sid)
        else:src.append_row(row,value_input_option="RAW");added.append(sid)
        onotes=json.dumps({"district":x["district"],"type":x["type"],"bedrooms":x["beds"],"bathrooms":x["baths"],"pool":x["pool"],"restrictions":x["restrictions"],"original_listing_text":x["text"],"translation_ru":None,"free_periods":x["availability"],"occupied_periods":"not provided","seasonal_prices":x["stay"],"minimum_stay":x["stay"],"booking_terms":"Advance, payment method/deadline, cancellation and booking point require owner confirmation","last_reply":None,"conversation_url":None,"contact_internal":x["contact"],"photo_fingerprints":x["photos"],"last_checked":now},ensure_ascii=False)
        orow=[now,sid,x["owner"],url,owner_url,x["availability"],x["price"],x["deposit"],x["utilities"],"Advance/payment method, cancellation and booking point require owner confirmation","awaiting_contact",onotes]
        if sid in oi:own.update(f"A{oi[sid]}:L{oi[sid]}",[orow],value_input_option="RAW")
        else:own.append_row(orow,value_input_option="RAW")
    counts={str(n):sum(1 for x in ITEMS if x["beds"]==n) for n in (1,2,3)}
    result={"enabled":True,"added":added,"updated":updated,"count":len(ITEMS),"bedrooms":counts,"exclusions":EXCLUSIONS,"new_replies":0}
    log.info("RECORD_FB_SCAN_20260830_EVENING_DONE %s",json.dumps(result,ensure_ascii=False));return result
